package fr.retouchephoto.app;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.view.*;import android.widget.*;import java.io.*;
public class MainActivity extends Activity {
 Bitmap base,overlay,result;ImageView preview;SeekBar bright,contrast,saturation;float dx=0,dy=0,scale=1,angle=0,opacity=1;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(12,12,12,12);TextView title=new TextView(this);title.setText("RE-touchephoto");title.setTextSize(23);l.addView(title);preview=new ImageView(this);preview.setBackgroundColor(0xff252525);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);l.addView(preview,new LinearLayout.LayoutParams(-1,0,1));btn(l,"Ouvrir photo",()->choose(1));btn(l,"Ajouter calque photo",()->choose(2));bright=slider(l,"Luminosité");contrast=slider(l,"Contraste");saturation=slider(l,"Saturation");btn(l,"Calque gauche",()->{dx-=30;render();});btn(l,"Calque droite",()->{dx+=30;render();});btn(l,"Calque haut",()->{dy-=30;render();});btn(l,"Calque bas",()->{dy+=30;render();});btn(l,"Taille calque",()->{scale=scale>=1.5f?0.5f:scale+0.25f;render();});btn(l,"Rotation 15°",()->{angle+=15;render();});btn(l,"Opacité",()->{opacity=opacity<=0.2f?1:opacity-0.2f;render();});btn(l,"Supprimer calque",()->{overlay=null;render();});btn(l,"Exporter PNG",()->save());setContentView(l);}
 void btn(LinearLayout l,String name,Runnable r){Button b=new Button(this);b.setText(name);l.addView(b);b.setOnClickListener(v->r.run());}
 SeekBar slider(LinearLayout l,String name){TextView t=new TextView(this);t.setText(name);l.addView(t);SeekBar s=new SeekBar(this);s.setMax(200);s.setProgress(100);l.addView(s);s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar v,int n,boolean u){render();}public void onStartTrackingTouch(SeekBar v){}public void onStopTrackingTouch(SeekBar v){}});return s;}
 void choose(int code){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,code);}
 protected void onActivityResult(int code,int status,Intent data){super.onActivityResult(code,status,data);if(status!=RESULT_OK||data==null)return;try(InputStream in=getContentResolver().openInputStream(data.getData())){Bitmap b=BitmapFactory.decodeStream(in);if(b==null)return;if(code==1){base=b;overlay=null;}else overlay=b;render();}catch(Exception e){toast(e.toString());}}
 void render(){if(base==null)return;int w=base.getWidth(),h=base.getHeight();Bitmap out=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(out);Paint p=new Paint(3);float co=contrast==null?1:contrast.getProgress()/100f,br=bright==null?0:(bright.getProgress()-100)*1.8f,sa=saturation==null?1:saturation.getProgress()/100f;ColorMatrix sat=new ColorMatrix();sat.setSaturation(sa);ColorMatrix adj=new ColorMatrix(new float[]{co,0,0,0,br,0,co,0,0,br,0,0,co,0,br,0,0,0,1,0});sat.postConcat(adj);p.setColorFilter(new ColorMatrixColorFilter(sat));c.drawBitmap(base,0,0,p);p.setColorFilter(null);if(overlay!=null){int ow=Math.round(overlay.getWidth()*scale),oh=Math.round(overlay.getHeight()*scale);float fit=Math.min((float)w/Math.max(ow,1),(float)h/Math.max(oh,1))*0.6f;ow=Math.max(1,Math.round(ow*fit));oh=Math.max(1,Math.round(oh*fit));p.setAlpha(Math.round(255*opacity));c.save();c.rotate(angle,w/2f+dx,h/2f+dy);c.drawBitmap(overlay,null,new RectF((w-ow)/2f+dx,(h-oh)/2f+dy,(w+ow)/2f+dx,(h+oh)/2f+dy),p);c.restore();}result=out;preview.setImageBitmap(out);}
 void save(){if(result==null){toast("Ouvrez une photo");return;}try{android.content.ContentValues v=new android.content.ContentValues();v.put(android.provider.MediaStore.Images.Media.DISPLAY_NAME,"RE-touchephoto-"+System.currentTimeMillis()+".png");v.put(android.provider.MediaStore.Images.Media.MIME_TYPE,"image/png");Uri uri=getContentResolver().insert(android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);try(OutputStream o=getContentResolver().openOutputStream(uri)){result.compress(Bitmap.CompressFormat.PNG,100,o);}toast("Image enregistrée");}catch(Exception e){toast(e.toString());}}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}